// Loader script that dynamically loads the real xlsx.full.min.js from the CDN (unpkg)
// The user requested the real version from CDN, so this loader pulls it at runtime.
(function(){
  var s = document.createElement('script');
  s.src = 'https://unpkg.com/xlsx/dist/xlsx.full.min.js';
  s.async = false; // load synchronously so code can use XLSX immediately
  document.head.appendChild(s);
})();
